// Generated by .github/skills/regenerate-abom-fixtures/scripts/regen-closure-fixture.sh: the CLI's
// output over the staged tree below, and over each repository's own files built regularly.
const (
	closureTree            = "../../ql/actions/graph-extraction/test/ResolvedCallees"
	closureFixtures        = "../../testdata/closure/"
	closureFindingsFixture = closureFixtures + "findings.sarif"
)

// The commits the crawl analyzed each repository at.
var closureCommits = map[string]string{
	"octo/app":         strings.Repeat("a", 40),
	"vendor/comp":      strings.Repeat("c", 40),
	"vendor/inner":     strings.Repeat("1", 40),
	"vendor/rw":        strings.Repeat("2", 40),
	"actions/checkout": strings.Repeat("3", 40),
}

// closureFiles is each repository's own checkout, rebuilt from the staged fixture tree.
func closureFiles(t *testing.T) map[string]map[string]string {
	t.Helper()
	read := func(rel string) string {
		body, err := os.ReadFile(filepath.Join(closureTree, filepath.FromSlash(rel)))
		if err != nil {
			t.Fatalf("reading the fixture: %v", err)
		}
		return string(body)
	}
	return map[string]map[string]string{
		"octo/app": {
			".github/workflows/pr.yml":         read(".github/workflows/pr.yml"),
			".github/actions/local/action.yml": read(".github/actions/local/action.yml"),
		},
		"vendor/comp":  {"action.yml": read(".github/actions/external/vendor/comp/action.yml")},
		"vendor/inner": {"action.yml": read(".github/actions/external/vendor/inner/action.yml")},
		"vendor/rw": {".github/workflows/reuse.yml": read(
			".github/workflows/external/vendor/rw/.github/workflows/reuse.yml")},
		"actions/checkout": {"action.yml": "name: checkout\nruns:\n  using: node20\n  main: dist/index.js\n"},
	}
}

// closureFetcher serves each repository's checkout at whatever commit is asked for.
type closureFetcher struct {
	files map[string]map[string]string
}

func (f *closureFetcher) Fetch(_ context.Context, dest, owner, repo, ref string) (Tree, error) {
	full := owner + "/" + repo
	files, ok := f.files[full]
	if !ok {
		return Tree{}, fmt.Errorf("%w: %s does not exist", ErrUnavailable, full)
	}
	for rel, body := range files {
		path := filepath.Join(dest, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			return Tree{}, err
		}
		if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
			return Tree{}, err
		}
	}
	return Tree{Dir: dest, Ref: ref, SHA: strings.ToLower(ref)}, nil
}

// closureBuilder records each staged tree as it was handed over, because the work directory is
// gone by the time a test can look.
type closureBuilder struct {
	mu       sync.Mutex
	trees    []map[string]string
	includes [][]string
}

func (b *closureBuilder) CreateDatabase(_ context.Context, _, dbDir, _ string) error {
	return writeDatabase(dbDir)
}

func (b *closureBuilder) CreateDatabaseIndexing(
	_ context.Context, srcDir, dbDir, _ string, includes []string,
) error {
	files := map[string]string{}
	if err := filepath.WalkDir(srcDir, func(path string, d os.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}
		rel, _ := filepath.Rel(srcDir, path)
		body, err := os.ReadFile(path)
		files[filepath.ToSlash(rel)] = string(body)
		return err
	}); err != nil {
		return err
	}
	b.mu.Lock()
	b.trees = append(b.trees, files)
	b.includes = append(b.includes, append([]string(nil), includes...))
	b.mu.Unlock()
	return writeDatabase(dbDir)
}

func writeDatabase(dbDir string) error {
	if err := os.MkdirAll(dbDir, 0o755); err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(dbDir, "codeql-database.yml"),
		[]byte("creationMetadata:\n  cliVersion: 2.27.1\n"), 0o644)
}

// versionedResolver is the fake resolver reporting the CodeQL the fixtures were generated with.
type versionedResolver struct{ *fakeResolver }

func (versionedResolver) Version(context.Context) (string, error) { return "2.27.1", nil }

type closureWorld struct {
	h       *harness
	builder *closureBuilder
	opts    ClosureOptions
}

// newClosureWorld is a crawled organization as the crawl leaves it: an owned repository analyzed
// at one commit, everything its workflows reach analyzed at the commit its reference resolved to,
// and the owned tier bound to a suite with a findings lane.
func newClosureWorld(t *testing.T) *closureWorld {
	t.Helper()
	h := newHarness(t)
	w := &closureWorld{
		h:       h,
		builder: &closureBuilder{},
		opts:    ClosureOptions{WorkDir: t.TempDir()},
	}
	h.expander.Fetcher = &closureFetcher{files: closureFiles(t)}
	h.expander.Builder = w.builder
	h.expander.Analyzer = closureAnalyzer{}
	bindLanes(t, h, "abom/edges", "Unpinned.ql")
	h.expander.Resolver = versionedResolver{h.expander.Resolver.(*fakeResolver)}
	if err := h.store.SetTierSuites(store.TierOwned, []string{"mixed.qls"}); err != nil {
		t.Fatalf("SetTierSuites: %v", err)
	}
	h.own(item("octo", "app", "", 0))

	s := h.store
	if _, err := s.UpsertRepository("octo/app", ""); err != nil {
		t.Fatal(err)
	}
	for _, name := range []string{"vendor/comp", "vendor/inner", "vendor/rw", "actions/checkout"} {
		if _, err := s.InsertUpstreamRepository(name); err != nil {
			t.Fatal(err)
		}
	}
	for _, row := range []struct {
		key, ref, owner, repo, subpath, commit string
		depth                                  int
	}{
		{"octo/app", "", "octo", "app", "", closureCommits["octo/app"], 0},
		{"actions/checkout", "v4", "actions", "checkout", "", closureCommits["actions/checkout"], 1},
		{"vendor/comp", "v1", "vendor", "comp", "", closureCommits["vendor/comp"], 1},
		{"vendor/rw/.github/workflows/reuse.yml", "v1", "vendor", "rw", ".github/workflows/reuse.yml",
			closureCommits["vendor/rw"], 1},
		{"vendor/inner", "v2", "vendor", "inner", "", closureCommits["vendor/inner"], 2},
	} {
		if _, err := s.DB().Exec(`INSERT INTO abom_frontier (node_key, ref, owner, repo, subpath,
			depth, status, enqueued_at, resolved_sha, analyzed_at) VALUES (?, ?, ?, ?, ?, ?, 'done',
			'2026-09-01T00:00:00Z', ?, '2026-09-01T00:00:00Z')`,
			row.key, row.ref, row.owner, row.repo, row.subpath, row.depth, row.commit); err != nil {
			t.Fatal(err)
		}
	}
	for _, repository := range []string{"octo/app", "vendor/comp", "vendor/inner", "vendor/rw"} {
		w.regular(t, repository)
	}
	if _, err := s.LinkFindingsToNodes(); err != nil {
		t.Fatal(err)
	}
	return w
}

// regular ingests what the CLI reported over one repository's own checkout, as the crawl would.
func (w *closureWorld) regular(t *testing.T, repository string) {
	t.Helper()
	s := w.h.store
	name := strings.Replace(repository, "/", "-", 1)
	edges, err := s.RecordQueryRun(store.QueryRun{QueryID: "abom/edges", Repository: repository,
		DBCommit: closureCommits[repository], AnalysisMode: store.AnalysisModeRegular,
		RecordedBy: store.RecordedByCrawl})
	if err != nil {
		t.Fatal(err)
	}
	in := ingest.New(s, w.h.expander.Writer)
	f, err := os.Open(closureFixtures + "regular-" + name + "-edges.json")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	if _, err := in.EdgesFromBQRS(f, ingest.Options{Repository: repository, QueryRunID: edges}); err != nil {
		t.Fatalf("ingesting %s's edges: %v", repository, err)
	}
	if err := w.h.expander.Writer.Flush(); err != nil {
		t.Fatal(err)
	}
	findings, err := s.RecordQueryRun(store.QueryRun{QueryID: "abom-findings.qls",
		Repository: repository, DBCommit: closureCommits[repository],
		AnalysisMode: store.AnalysisModeRegular, RecordedBy: store.RecordedByCrawl})
	if err != nil {
		t.Fatal(err)
	}
	sarif, err := os.Open(closureFixtures + "regular-" + name + "-findings.sarif")
	if err != nil {
		t.Fatal(err)
	}
	defer sarif.Close()
	if _, err := in.FindingsFromSARIF(sarif, ingest.Options{Repository: repository,
		QueryRunID: findings, CLIVersion: "2.27.1"}); err != nil {
		t.Fatalf("ingesting %s's findings: %v", repository, err)
	}
}

// closureAnalyzer stands in for `database analyze` over the staged closure.
type closureAnalyzer struct{}

func (closureAnalyzer) AnalyzeQueries(_ context.Context, _ string, _ []string, sarifPath string) error {
	body, err := os.ReadFile(closureFindingsFixture)
	if err != nil {
		return err
	}
	if err := os.MkdirAll(filepath.Dir(sarifPath), 0o755); err != nil {
		return err
	}
	return os.WriteFile(sarifPath, body, 0o644)
}

// totals are the numbers a closure must leave exactly as they were.
func (w *closureWorld) totals(t *testing.T) string {
	t.Helper()
	var out []string
	for _, q := range []string{
		`SELECT COUNT(*) FROM abom_node_live`,
		`SELECT COUNT(*) FROM abom_edge_live`,
		`SELECT COUNT(*) FROM abom_edge_regular`,
		`SELECT COUNT(*) FROM abom_finding_regular`,
		`SELECT COUNT(*) FROM repository`,
		`SELECT COUNT(*) || ':' || COUNT(repository_url) FROM repository`,
		`SELECT GROUP_CONCAT(node_key || '@' || ref || '=' || status, ',') FROM abom_frontier`,
		// What a suite resolves to and what a query declares are the crawl's records; a closure
		// resolves the owned tier to run it and has no business rewriting either.
		`SELECT COUNT(*) || ':' || COALESCE(MAX(resolved_at), '') FROM abom_suite_query`,
		`SELECT COUNT(*) || ':' || COALESCE(MAX(resolved_at), '') FROM abom_query_metadata`,
	} {
		var v string
		if err := w.h.store.DB().QueryRow(q).Scan(&v); err != nil {
			t.Fatalf("%s: %v", q, err)
		}
		out = append(out, v)
	}
	closure, err := w.h.store.SubmissionClosure("octo/app")
	if err != nil {
		t.Fatal(err)
	}
	out = append(out, fmt.Sprint(closure))
	return strings.Join(out, "\n")
}

// builtClosure builds the fixture world's closure once, keeping the totals from before it.
func builtClosure(t *testing.T) (*closureWorld, ClosureReport, string) {
	t.Helper()
	w := newClosureWorld(t)
	before := w.totals(t)
	report, err := w.h.expander.BuildClosure(context.Background(), "octo/app", w.opts)
	if err != nil {
		t.Fatalf("BuildClosure: %v", err)
	}
	if len(w.builder.trees) != 1 {
		t.Fatalf("built %d closure databases, want one", len(w.builder.trees))
	}
	return w, report, before
}

// The closure stages exactly what the crawl says the owned repository's workflows reach, at the
// commits the crawl analyzed: the tree it hands to the extractor is the checked-in fixture byte
// for byte, and the staged reusable workflow is indexed.
func TestAClosureDatabaseStagesWhatTheCrawlReached(t *testing.T) {
	w, report, _ := builtClosure(t)
	if !reflect.DeepEqual(w.builder.includes[0], closure.IndexIncludes) {
		t.Errorf("indexed with %v, want %v", w.builder.includes[0], closure.IndexIncludes)
	}
	want := closureFiles(t)
	staged := map[string]string{}
	for rel, body := range want["octo/app"] {
		staged[rel] = body
	}
	staged[".github/actions/external/vendor/comp/action.yml"] = want["vendor/comp"]["action.yml"]
	staged[".github/actions/external/vendor/inner/action.yml"] = want["vendor/inner"]["action.yml"]
	staged[".github/workflows/external/vendor/rw/.github/workflows/reuse.yml"] =
		want["vendor/rw"][".github/workflows/reuse.yml"]
	if !reflect.DeepEqual(w.builder.trees[0], staged) {
		t.Errorf("the extractor was handed\n%v\nwant the staged fixture\n%v",
			keysOf(w.builder.trees[0]), keysOf(staged))
	}
	if report.Commit != closureCommits["octo/app"] || report.Anchored || len(report.Unstaged) != 0 {
		t.Errorf("rooted at %s anchored=%v unstaged=%v", report.Commit, report.Anchored, report.Unstaged)
	}
	if len(report.Staged) != 3 || len(report.Skipped) != 1 ||
		report.Skipped[0].Repository != "actions/checkout" {
		t.Errorf("staged %d, skipped %+v; want three callables and the JavaScript action named",
			len(report.Staged), report.Skipped)
	}
}

// What the closure found is tallied against what the crawl already holds: which findings were
// already on record, and which attach to no node.
func TestAClosureDatabaseTalliesWhatItFound(t *testing.T) {
	_, report, _ := builtClosure(t)
	if got := report.Tally; got.Findings != 9 || got.Shared != 6 || got.ExtendedOnly() != 3 {
		t.Errorf("tally %+v; want 9 findings, 6 already reported regularly", got)
	}
	// Both injection sinks are composites or workflows with no `uses:` step, and the graph models
	// what a `uses:` line touches, so neither file is a node. Pinned because it is the gap a
	// cross-boundary finding falls into, not because it is right.
	if report.Tally.Unattached != 3 {
		t.Errorf("%d of the closure's findings attach to no node, want the 3 in files the "+
			"graph holds no node for", report.Tally.Unattached)
	}
}

// The headline: every number that existed before a closure is exactly what it was after it,
// because everything a closure writes is extended and every existing total reads regular.
func TestAClosureDatabaseMovesNoExistingTotal(t *testing.T) {
	w, _, before := builtClosure(t)
	if after := w.totals(t); after != before {
		t.Errorf("a closure moved an existing total:\nbefore\n%s\nafter\n%s", before, after)
	}
}

// The run names the owned repository it is about and the inputs it was built from, so a finding
// seen through it can say how to reproduce it.
func TestAClosureDatabaseRecordsItsRunAndManifest(t *testing.T) {
	w, report, _ := builtClosure(t)
	var mode, by, digest, repository, commit string
	if err := w.h.store.DB().QueryRow(`SELECT analysis_mode, recorded_by, closure_digest,
		repository, db_commit FROM abom_query_run WHERE row_id = ?`, report.QueryRunID).
		Scan(&mode, &by, &digest, &repository, &commit); err != nil {
		t.Fatalf("reading the closure run: %v", err)
	}
	if mode != store.AnalysisModeExtended || by != store.RecordedByClosure || digest != report.Digest ||
		repository != "octo/app" || commit != closureCommits["octo/app"] {
		t.Errorf("recorded %s %s %s %s@%s", mode, by, digest, repository, commit)
	}
	manifest, ok, err := w.h.store.ClosureManifestOf(report.Digest)
	if err != nil || !ok || len(manifest.Members) != 3 {
		t.Errorf("manifest %+v, %v, %v; want the three staged callees", manifest, ok, err)
	}
	for _, m := range manifest.Members {
		if m.Commit != closureCommits[m.Repository] {
			t.Errorf("%s staged at %s, want the commit the crawl analyzed, %s",
				m.Repository, m.Commit, closureCommits[m.Repository])
		}
	}
}

// A closure whose identity is on record has been answered: CodeQL is deterministic, so building it
// again would cost an extraction and say nothing new.
func TestAClosureAlreadyOnRecordIsNotBuiltAgain(t *testing.T) {
	w := newClosureWorld(t)
	first, err := w.h.expander.BuildClosure(context.Background(), "octo/app", w.opts)
	if err != nil {
		t.Fatalf("BuildClosure: %v", err)
	}
	again, err := w.h.expander.BuildClosure(context.Background(), "octo/app", w.opts)
	if err != nil {
		t.Fatalf("BuildClosure again: %v", err)
	}
	if !again.AlreadyAnalyzed || again.Digest != first.Digest {
		t.Errorf("the second closure was not recognized: %+v", again)
	}
	if len(w.builder.trees) != 1 {
		t.Errorf("built %d closure databases for one identity", len(w.builder.trees))
	}
}

// The closure is rooted at an owned repository because that is the unit somebody can act on, and
// the unit a collision is reportable in.
func TestAClosureIsRootedOnlyAtAnOwnedRepository(t *testing.T) {
	w := newClosureWorld(t)
	// Analyzed at its default branch like any root, so ownership is the only thing missing.
	if _, err := w.h.store.DB().Exec(`INSERT INTO abom_frontier (node_key, ref, owner, repo, depth,
		status, enqueued_at, resolved_sha) VALUES ('vendor/comp', '', 'vendor', 'comp', 1, 'done',
		'2026-09-01T00:00:00Z', ?)`, closureCommits["vendor/comp"]); err != nil {
		t.Fatal(err)
	}
	_, err := w.h.expander.BuildClosure(context.Background(), "vendor/comp", w.opts)
	if err == nil || !strings.Contains(err.Error(), "declared scope") {
		t.Fatalf("err = %v; a closure was rooted at a repository nobody declared", err)
	}
	if len(w.builder.trees) != 0 {
		t.Error("a database was built anyway")
	}
}

// A commit is read from the store and becomes a directory, so one that is not a commit id is never
// fetched: the member is named as left out instead.
func TestAMemberWhoseCommitIsNotACommitIdIsLeftOutRatherThanFetched(t *testing.T) {
	w := newClosureWorld(t)
	if _, err := w.h.store.DB().Exec(`UPDATE abom_frontier SET resolved_sha = '../outside'
		WHERE node_key = 'actions/checkout'`); err != nil {
		t.Fatal(err)
	}
	report, err := w.h.expander.BuildClosure(context.Background(), "octo/app", w.opts)
	if err != nil {
		t.Fatalf("BuildClosure: %v", err)
	}
	if len(report.Skipped) != 0 || len(report.Unstaged) != 1 || report.Unstaged[0].Uses != "actions/checkout" ||
		!strings.Contains(report.Unstaged[0].Reason, "not name a repository at a commit") {
		t.Errorf("skipped %+v, unstaged %+v; want actions/checkout named as not a repository at a "+
			"commit, never fetched", report.Skipped, report.Unstaged)
	}
}

func keysOf(m map[string]string) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}
